1	// Package indexroom implements chain ingestion with optional block
2	// timestamps, reorg handling, consistent paginated transaction queries, and
3	// time-bucketed transaction statistics over the main chain.
4	package indexroom
5	
6	import "sync"
7	
8	// Block is one ingested block with its transactions.
9	//
10	// Time is the optional block timestamp as non-negative Unix seconds. A nil
11	// pointer means the block carries no timestamp and is distinct from a
12	// timestamp of zero. Append and Reorg reject negative values; stored blocks
13	// keep their own copy, so mutating the pointer or its target after a call
14	// never affects the index. Block timestamps need not be monotonic: equal
15	// values and values that decrease with height are both accepted.
16	type Block struct {
17		Height int64
18		Hash   string
19		Parent string
20		Txs    []string
21		Time   *int64
22	}
23	
24	// Index is the durable chain view.
25	//
26	// Append, Reorg, QueryTxs, QueryTimeStats, Export, and Restore are safe for
27	// concurrent use; the exported fields are meant for read-only inspection
28	// after all calls have finished.
29	type Index struct {
30		Blocks map[int64]Block
31		ByHash map[string]int64
32		Tip    int64
33	
34		mu  sync.Mutex
35		key [32]byte
36	}
37	
38	// New returns an empty index.
39	func New() *Index {
40		return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
41	}
42	
43	// Append accepts a block only when it extends the current tip, keeping the
44	// chain linear. Re-submitting a block identical to one already on the main
45	// chain is a successful no-op. A rejected append leaves the index untouched.
46	func (index *Index) Append(block Block) error {
47		index.mu.Lock()
48		defer index.mu.Unlock()
49		return index.appendLocked(block)
50	}
51	
52	func (index *Index) appendLocked(block Block) error {
53		if block.Hash == "" {
54			return errInvalid("block needs a hash")
55		}
56		if block.Time != nil && *block.Time < 0 {
57			return errInvalid("block time must not be negative")
58		}
59		if index.Tip == 0 {
60			// Empty index: only the first block at height 1 is accepted; its
61			// parent becomes the chain start identifier and need not be indexed.
62			if block.Height != 1 {
63				return errInvalid("first block must be at height 1")
64			}
65			index.storeLocked(block)
66			return nil
67		}
68		if old, exists := index.Blocks[block.Height]; exists {
69			if sameBlock(old, block) {
70				return nil
71			}
72			return errInvalid("height already indexed with different content")
73		}
74		if block.Height != index.Tip+1 {
75			return errInvalid("block height must extend the current tip")
76		}
77		if block.Parent != index.Blocks[index.Tip].Hash {
78			return errInvalid("parent does not match the current tip")
79		}
80		if _, exists := index.ByHash[block.Hash]; exists {
81			return errInvalid("hash already indexed at another height")
82		}
83		index.storeLocked(block)
84		return nil
85	}
86	
87	// Reorg replaces the tip range with an alternate branch and reports the
88	// dropped old heights in ascending order. The branch is validated in full
89	// before anything is applied, so a rejected reorg leaves the index exactly
90	// as it was. Heights whose old block is identical to the new one are not
91	// reported; re-submitting the branch already in effect returns an empty list.
92	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
93		index.mu.Lock()
94		defer index.mu.Unlock()
95	
96		if len(blocks) == 0 {
97			return nil, errInvalid("empty branch")
98		}
99		ancestor, ok := index.ByHash[blocks[0].Parent]
100		if !ok {
101			return nil, errInvalid("branch parent is unknown")
102		}
103		if blocks[0].Height != ancestor+1 {
104			return nil, errInvalid("branch must start at the ancestor height plus one")
105		}
106		seen := make(map[string]bool, len(blocks))
107		for i, block := range blocks {
108			if block.Hash == "" {
109				return nil, errInvalid("block needs a hash")
110			}
111			if block.Time != nil && *block.Time < 0 {
112				return nil, errInvalid("block time must not be negative")
113			}
114			if seen[block.Hash] {
115				return nil, errInvalid("duplicate hash inside branch")
116			}
117			seen[block.Hash] = true
118			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
119				return nil, errInvalid("hash conflicts with a retained block")
120			}
121			if i > 0 {
122				prev := blocks[i-1]
123				if block.Height != prev.Height+1 {
124					return nil, errInvalid("branch heights must be consecutive")
125				}
126				if block.Parent != prev.Hash {
127					return nil, errInvalid("branch parent does not match the previous block")
128				}
129			}
130		}
131	
132		// Everything validated; compute the dropped heights before mutating.
133		newTip := blocks[len(blocks)-1].Height
134		dropped := []int64{}
135		for height := ancestor + 1; height <= index.Tip; height++ {
136			if height > newTip {
137				dropped = append(dropped, height)
138				continue
139			}
140			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
141				dropped = append(dropped, height)
142			}
143		}
144		for height := ancestor + 1; height <= index.Tip; height++ {
145			delete(index.ByHash, index.Blocks[height].Hash)
146			delete(index.Blocks, height)
147		}
148		index.Tip = ancestor
149		for _, block := range blocks {
150			index.storeLocked(block)
151		}
152		return dropped, nil
153	}
154	
155	// storeLocked records a validated block, copying its transactions and
156	// timestamp so later caller-side mutation cannot alter the stored block.
157	func (index *Index) storeLocked(block Block) {
158		if block.Txs != nil {
159			txs := make([]string, len(block.Txs))
160			copy(txs, block.Txs)
161			block.Txs = txs
162		}
163		if block.Time != nil {
164			t := *block.Time
165			block.Time = &t
166		}
167		index.Blocks[block.Height] = block
168		index.ByHash[block.Hash] = block.Height
169		index.Tip = block.Height
170	}
171	
172	// sameBlock reports whether two blocks are identical: same height, hash,
173	// parent, transactions in order, and timestamp presence and value. An empty
174	// tx list equals a missing one, but a missing timestamp never equals zero.
175	func sameBlock(a, b Block) bool {
176		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
177			return false
178		}
179		if len(a.Txs) != len(b.Txs) {
180			return false
181		}
182		for i := range a.Txs {
183			if a.Txs[i] != b.Txs[i] {
184				return false
185			}
186		}
187		if (a.Time == nil) != (b.Time == nil) {
188			return false
189		}
190		return a.Time == nil || *a.Time == *b.Time
191	}
192	
