// txChain builds a chain with one block per tx list, hashes h1..hN.
func txChain(t *testing.T, txs ...[]string) *Index {
	t.Helper()
	index := New()
	for i, blockTxs := range txs {
		height := int64(i + 1)
		parent := "genesis"
		if height > 1 {
			parent = fmt.Sprintf("h%d", height-1)
